<script setup>
import ContentLoading from "@/components/shared/ContentLoading.vue"
import { computed,nextTick,onMounted,onUnmounted,ref,watch } from 'vue'
import { imageSearchPreview,loadWebImageLibrary,mediaSearchText,searchIgdbMedia } from '@/services/imageLibrary'
const props=defineProps({game:{type:Object,default:()=>({})},target:{type:String,default:'image'}})
const emit=defineEmits(['close','select'])
const initialGameQuery=(props.game.nameEn||props.game.nameEs||'').trim()
const source=ref(initialGameQuery.length>=2?'igdb':'web'),webQuery=ref(props.game.nameEs||props.game.nameEn||''),igdbQuery=ref(initialGameQuery)
const web=ref({images:[],postCount:0,hasMore:false}),igdb=ref({images:[],games:[]}),loading=ref(false),error=ref(''),searched=ref(false),selected=ref(null),type=ref('all'),gameFilter=ref('all'),visible=ref(24),dialog=ref(null)
let controller,sequence=0,oldOverflow,oldFocus
const queryText=computed({get:()=>source.value==='web'?webQuery.value:igdbQuery.value,set:value=>{if(source.value==='web')webQuery.value=value;else igdbQuery.value=value}})
const matches=computed(()=>{
 if(source.value==='web'){const terms=mediaSearchText(webQuery.value).split(' ').filter(Boolean);return web.value.images.filter(i=>terms.every(term=>i.searchText.includes(term)))}
 const order={artwork:0,screenshot:1,cover:2}
 return igdb.value.images.filter(i=>(type.value==='all'||i.type===type.value)&&(gameFilter.value==='all'||String(i.gameId)===gameFilter.value)).sort((a,b)=>(order[a.type]??3)-(order[b.type]??3))
})
watch([source,queryText,type,gameFilter],()=>{visible.value=24;selected.value=null;error.value=''})
async function library(options={}){const token=++sequence;loading.value=true;error.value='';try{const data=await loadWebImageLibrary(options);if(token===sequence)web.value=data}catch(e){if(token===sequence)error.value=e.message}finally{if(token===sequence)loading.value=false}}
async function search(){
 if(source.value==='web'){visible.value=24;return}
 controller?.abort();controller=new AbortController();const token=++sequence;loading.value=true;error.value='';searched.value=true;selected.value=null
 const query=igdbQuery.value.trim(),signal=controller.signal
 if(query.length<2){loading.value=false;return}
 igdb.value={images:[],games:[]}
 try{let data=await searchIgdbMedia(query,{signal});if(token!==sequence)return;if(!data.images.length&&props.game.nameEs&&props.game.nameEn&&query===props.game.nameEn.trim()&&props.game.nameEs.trim()!==query){data=await searchIgdbMedia(props.game.nameEs,{signal})}if(token===sequence){igdb.value=data;gameFilter.value='all';type.value='all'}}catch(e){if(token===sequence&&e.name!=='AbortError')error.value=e.message}finally{if(token===sequence)loading.value=false}
}
function chooseSource(value){if(source.value===value)return;controller?.abort();sequence++;loading.value=false;source.value=value;if(value==='web')library()}
function keys(event){if(event.key==='Escape'){event.preventDefault();event.stopPropagation();emit('close')}if(event.key!=='Tab')return;const items=[...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')].filter(e=>e.offsetParent!==null);const first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last?.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus()}}
onMounted(async()=>{oldOverflow=document.body.style.overflow;oldFocus=document.activeElement;document.body.style.overflow='hidden';await nextTick();dialog.value.querySelector('button')?.focus();if(source.value==='igdb')search();else library()})
onUnmounted(()=>{sequence++;controller?.abort();document.body.style.overflow=oldOverflow;oldFocus?.focus?.()})
</script>
<template>
 <Teleport to="body"><div class="image-search-backdrop" @click.self="emit('close')"><section ref="dialog" class="image-search-dialog" role="dialog" aria-modal="true" aria-labelledby="image-search-heading" @keydown="keys">
  <header><div><span>BIBLIOTECA DE IMÁGENES</span><h2 id="image-search-heading">{{ target==='logo'?'Buscar logo':'Buscar imagen' }}</h2><p>Reutiliza imágenes de tus publicaciones o elige arte del juego.</p></div><button type="button" aria-label="Cerrar búsqueda de imágenes" @click="emit('close')">×</button></header>
  <nav class="image-source-tabs" aria-label="Origen de las imágenes"><button type="button" :aria-pressed="source==='web'" @click="chooseSource('web')">Imágenes de la web</button><button type="button" :aria-pressed="source==='igdb'" @click="chooseSource('igdb')">Juegos · IGDB</button></nav>
  <form class="image-search-form" @submit.prevent="search"><label class="image-search-label"><span>{{ source==='web'?'Buscar en las imágenes cargadas':'Nombre del juego (mejor en inglés)' }}</span><input v-model="queryText" type="search" maxlength="180" :placeholder="source==='web'?'Título, juego o sección...':'The Smurfs: Dreams'"/></label><button type="submit" :disabled="loading||(source==='igdb'&&queryText.trim().length<2)">{{ loading?'Buscando...':'Buscar' }}</button></form>
  <p v-if="source==='web'" class="image-search-hint">{{ web.postCount }} publicaciones cargadas. La búsqueda filtra sus portadas, secciones e imágenes sociales. Carga más para ampliar la biblioteca. <button type="button" :disabled="loading" @click="library({refresh:true})">Actualizar biblioteca</button></p>
  <p v-else class="image-search-hint">Usa arte o capturas para una invitación; también puedes elegir una carátula. <button v-if="game.nameEs&&game.nameEn&&game.nameEs!==game.nameEn" type="button" @click="igdbQuery=game.nameEs;search()">Buscar en español</button></p>
  <div v-if="source==='igdb'&&igdb.images.length" class="image-search-filters"><label>Juego<select v-model="gameFilter"><option value="all">Todos los resultados</option><option v-for="item in igdb.games" :key="item.id" :value="String(item.id)">{{ item.name }}</option></select></label><label>Tipo<select v-model="type"><option value="all">Todas las imágenes</option><option value="artwork">Arte</option><option value="screenshot">Capturas</option><option value="cover">Carátulas</option></select></label></div>
  <p v-if="error" class="image-search-error" role="alert">{{ error }}</p><ContentLoading v-if="loading" variant="inline" />
  <div class="image-search-content"><div><div class="image-search-grid"><button v-for="item in matches.slice(0,visible)" :key="item.id||item.url" type="button" :class="{selected:selected?.url===item.url}" :aria-pressed="selected?.url===item.url" @click="selected=item"><img :src="imageSearchPreview(item.url)" alt="" loading="lazy"/><strong>{{ item.gameName||item.postTitle }}</strong><small>{{ item.typeLabel||item.label }}</small></button></div><p v-if="!matches.length&&!loading" class="image-search-hint">{{ source==='igdb'&&!searched?'Pulsa Buscar para consultar el juego.':'No hay imágenes que coincidan. Prueba otro nombre o carga más publicaciones.' }}</p><button v-if="matches.length>visible" class="image-search-more" type="button" @click="visible+=24">Ver más imágenes</button><button v-else-if="source==='web'&&web.hasMore" class="image-search-more" type="button" :disabled="loading" @click="library({more:true})">Cargar más publicaciones</button></div>
   <aside class="image-search-preview"><template v-if="selected"><img :src="imageSearchPreview(selected.url)" alt="Vista previa de la imagen seleccionada"/><strong>{{ selected.gameName||selected.postTitle }}</strong><small>{{ selected.typeLabel||selected.label }}</small><button type="button" class="image-search-use" @click="emit('select',selected)">Usar esta imagen</button></template><p v-else>Selecciona una imagen para verla antes de usarla.</p></aside>
  </div>
 </section></div></Teleport>
</template>
<style scoped>
