image-search-content{display:grid;grid-template-columns:minmax(0,1fr) 230px;gap:16px;min-height:200px}.image-search-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;max-height:42dvh;overflow:auto;padding:3px}.image-search-grid button{padding:6px;text-align:left;background:#171d31;min-width:0}.image-search-grid button.selected{border-color:#c4b5fd;background:#7c3aed33}.image-search-grid img{display:block;width:100%;height:95px;object-fit:cover;border-radius:6px;background:#050a17}.image-search-grid strong{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-size:11px;margin-top:6px;line-height:1.4}.image-search-grid small,.image-search-preview small{font-size:10px;color:#aebbd3;display:block;margin-top:4px}.image-search-preview{min-width:0;display:flex;flex-direction:column;gap:9px;border:1px solid #a78bfa22;background:#080d1e;border-radius:12px;padding:12px;font-size:12px;color:#adb9d1}.image-search-preview>img{width:100%;height:185px;object-fit:contain;border-radius:8px;background:#040715}.image-search-preview strong{color:#e2e8f0;overflow-wrap:anywhere}.image-search-dialog .image-search-use{background:linear-gradient(110deg,#7c3aed,#ad309f);color:white;margin-top:auto}.image-search-filters{display:flex;gap:10px}.image-search-filters label{display:grid;gap:6px;font-size:11px;min-width:0;flex:1}.image-search-more{margin-top:10px}@media(max-width:600px){.image-search-dialog{padding:16px;gap:12px}.image-search-dialog h2{font-size:22px}.image-search-content{grid-template-columns:1fr;gap:10px}.image-search-grid{grid-template-columns:repeat(2,minmax(0,1fr));max-height:31dvh}.image-search-grid img{height:95px}.image-search-preview{display:grid;grid-template-columns:80px minmax(0,1fr);align-items:center}.image-search-preview>img{height:80px;grid-row:1/4}.image-search-preview strong{font-size:11px}.image-search-preview p{grid-column:1/-1}.image-search-preview .image-search-use{grid-column:1/-1;min-height:40px}.image-search-form{gap:7px}.image-source-tabs button{flex:1;padding:9px}.image-search-filters{flex-wrap:wrap}}
